    o = off64.to(tl.int64)
    # Launch-constant key: all four words of (seed, offset) participate, so
    # seed bits 32..63 and offset bits 32..63 change the whole stream even when
    # the low words repeat.
    key = (
        (s & 0xFFFFFFFF).to(tl.uint32)
        ^ ((s >> 32).to(tl.uint32) * 0x7FEB352D)
        ^ (((o >> 32) & 0xFFFFFFFF).to(tl.uint32) * 0x2C1B3C6D)
    )
    h = ((o & 0xFFFFFFFF).to(tl.uint32) + off.to(tl.uint32)) ^ key
    h = h ^ (h >> 16)
    h = h * 0x7FEB352D
    h = h ^ (h >> 15)
